/**
 * Energy Price Graph – frontend module
 *
 * Adds a dynamic electricity price graph (import and, optionally, export
 * price) to the built-in Home Assistant Energy dashboard. The graph is a
 * standard statistics-graph card that follows the Energy date picker.
 *
 * This file is served and registered by the energy_price_graph integration;
 * its options arrive as query parameters on the module URL.
 *
 * How it works: the Energy dashboard views are generated by frontend
 * "strategies" (energy-view-strategy / energy-overview-view-strategy). We hook
 * the custom element registry so we can extend their generate() output before
 * first use. This relies on frontend internals: if a Home Assistant update changes
 * them, the Energy dashboard keeps working, just without the price graph.
 */

const params = new URL(import.meta.url).searchParams;
const OPT = {
  entity: params.get("entity") || null,
  exportEntity: params.get("export_entity") || null,
  showExport: params.get("export") !== "0",
  period: params.get("period") || "auto",
  views: (params.get("views") || "electricity,overview").split(","),
  title: params.get("title") || null,
  importName: params.get("import_name") || null,
  exportName: params.get("export_name") || null,
  minmax: params.get("minmax") === "1",
  // smooth | straight | stepped
  line: ["smooth", "straight", "stepped"].includes(params.get("line"))
    ? params.get("line")
    : "stepped",
};

// Marker key on our card config. The statistics-graph card ignores unknown
// keys, so it is safe to carry it along; we use it to recognise our cards.
const LINE_KEY = "energy_price_graph_line";

const TAG = "[energy-price-graph]";
const MARK = "__energyPriceInjected";

/**
 * Find the price sensors (import + export) in the energy preferences.
 * Supports the current schema (entity_energy_price[_export] on the grid
 * source) and the older one (flow_from / flow_to).
 */
async function findPriceEntities(hass) {
  let imp = OPT.entity;
  let exp = OPT.exportEntity;
  if (!imp || (!exp && OPT.showExport)) {
    try {
      const prefs = await hass.callWS({ type: "energy/get_prefs" });
      for (const src of prefs?.energy_sources || []) {
        if (src.type !== "grid") continue;
        // current schema
        imp = imp || src.entity_energy_price || null;
        exp = exp || src.entity_energy_price_export || null;
        // older schema
        for (const f of src.flow_from || []) imp = imp || f.entity_energy_price || null;
        for (const f of src.flow_to || []) exp = exp || f.entity_energy_price || null;
      }
    } catch (e) {
      console.warn(TAG, "could not read energy preferences", e);
    }
  }
  if (!OPT.showExport) exp = null;
  return { imp, exp };
}

/** Same colours as grid import / export on the Energy dashboard. */
function themeColor(varName, fallback) {
  try {
    const v = getComputedStyle(document.documentElement).getPropertyValue(varName).trim();
    if (/^#[0-9a-f]{3,8}$/i.test(v)) return v;
  } catch (e) { /* ignore */ }
  return fallback;
}

const LABELS = {
  en: { title: "Electricity price", imp: "Import", exp: "Export" },
  nl: { title: "Stroomprijs", imp: "Inkoop", exp: "Teruglevering" },
  de: { title: "Strompreis", imp: "Bezug", exp: "Einspeisung" },
};

function labels(hass) {
  const lang = (hass?.locale?.language || hass?.language || "en").split("-")[0];
  const l = LABELS[lang] || LABELS.en;
  return {
    title: OPT.title || l.title,
    imp: OPT.importName || l.imp,
    exp: OPT.exportName || l.exp,
  };
}

function priceCard({ imp, exp }, collectionKey, L) {
  const entities = [];
  const sameEntity = imp && exp && imp === exp;
  if (imp) {
    entities.push({
      entity: imp,
      name: sameEntity ? L.title : L.imp,
      color: themeColor("--energy-grid-consumption-color", "#488fc2"),
    });
  }
  if (exp && !sameEntity) {
    entities.push({
      entity: exp,
      name: L.exp,
      color: themeColor("--energy-grid-return-color", "#8353d1"),
    });
  }
  return {
    type: "statistics-graph",
    title: L.title,
    entities,
    stat_types: OPT.minmax ? ["mean", "min", "max"] : ["mean"],
    chart_type: "line",
    // "auto" is the card's default; leaving the key out keeps older frontends
    // (which do not know "auto") working.
    ...(OPT.period !== "auto" && { period: OPT.period }),
    energy_date_selection: true,
    collection_key: collectionKey,
    // A legend is only useful with more than one line.
    hide_legend: entities.length < 2 && !OPT.minmax,
    [LINE_KEY]: OPT.line,
    grid_options: { columns: "full" },
  };
}

/**
 * Older Home Assistant versions build the Energy views as a flat list of
 * cards (masonry / sidebar view) instead of sections.
 */
function injectIntoCards(view, card) {
  if (!Array.isArray(view.cards)) return false;
  const idx = view.cards.findIndex((c) => c.type === "energy-usage-graph");
  view.cards.splice(idx === -1 ? 0 : idx + 1, 0, card);
  return true;
}

/** Electricity tab: card directly after the energy usage graph. */
function injectElectricity(view, card) {
  if (injectIntoCards(view, card)) return true;
  for (const section of view.sections || []) {
    const cards = section.cards || [];
    const idx = cards.findIndex((c) => c.type === "energy-usage-graph");
    if (idx !== -1) {
      cards.splice(idx + 1, 0, card);
      return true;
    }
  }
  // No usage graph (e.g. hidden): put it at the top of the main section.
  const main = (view.sections || []).find((s) => s.column_span === 3);
  if (main) {
    main.cards = [card, ...(main.cards || [])];
    return true;
  }
  return false;
}

/** Summary tab: own section after the section with the energy usage graph. */
function injectOverview(view, card) {
  if (injectIntoCards(view, card)) return true;
  const sections = view.sections || (view.sections = []);
  const idx = sections.findIndex((s) =>
    (s.cards || []).some((c) => c.type === "energy-usage-graph")
  );
  const newSection = { type: "grid", cards: [card] };
  if (idx !== -1) sections.splice(idx + 1, 0, newSection);
  else sections.push(newSection);
  return true;
}

const TARGETS = {
  "energy-view-strategy": { key: "electricity", inject: injectElectricity },
  "energy-overview-view-strategy": { key: "overview", inject: injectOverview },
};

function patchStrategy(tag, ctor) {
  const target = TARGETS[tag];
  if (!target || !OPT.views.includes(target.key)) return;
  if (!ctor || typeof ctor.generate !== "function" || ctor[MARK]) return;

  const original = ctor.generate;
  ctor.generate = async function (config, hass, ...rest) {
    const view = await original.call(this, config, hass, ...rest);
    try {
      const found = await findPriceEntities(hass);
      if (!found.imp && !found.exp) {
        console.info(TAG, "no price sensor found, nothing added");
        return view;
      }
      const key = config?.collection_key || "energy_dashboard";
      target.inject(view, priceCard(found, key, labels(hass)));
    } catch (e) {
      console.error(TAG, "injection failed, dashboard left unchanged", e);
    }
    return view;
  };
  ctor[MARK] = true;
  console.info(TAG, `active on ${target.key}`);
}

// The energy strategies are only loaded when the Energy dashboard is opened.
// We hook the custom element registry so we can patch them before first use:
// - define(): patch when the strategy is registered;
// - get(): the dashboard looks the strategy up right before calling
//   generate(), so patching there is deterministic.
// The frontend may replace window.customElements with a scoped-registry
// polyfill after this module has run, so we (re)install the hooks on every
// registry object we see.
const HOOK = "__energyPriceGraphHooked";

function installRegistryHooks() {
  const reg = window.customElements;
  if (!reg || reg[HOOK]) return;
  const define = reg.define;
  const get = reg.get;
  try {
    reg.define = function (name, ctor, options) {
      if (name in TARGETS) patchStrategy(name, ctor);
      return define.call(this, name, ctor, options);
    };
    reg.get = function (name) {
      const ctor = get.call(this, name);
      if (ctor && name in TARGETS) patchStrategy(name, ctor);
      return ctor;
    };
    reg[HOOK] = true;
  } catch (e) {
    console.warn(TAG, "could not hook custom element registry", e);
  }
  for (const tag of Object.keys(TARGETS)) {
    const existing = get.call(reg, tag);
    if (existing) patchStrategy(tag, existing);
    reg
      .whenDefined(tag)
      .then(() => patchStrategy(tag, get.call(reg, tag)))
      .catch(() => {});
  }
  reg
    .whenDefined("ha-chart-base")
    .then(() => patchChartBase(get.call(reg, "ha-chart-base")))
    .catch(() => {});
}

/* ------------------------------------------------------------------------ *
 * Line style
 *
 * The statistics-graph card always draws line charts smoothed. For prices a
 * stepped line is more accurate (a price holds for the whole period), so we
 * adjust the series right before the chart renders — only for charts that
 * belong to one of our cards.
 * ------------------------------------------------------------------------ */

/** Walk up from the chart to the card that hosts it and read our marker. */
function lineStyleFor(chart) {
  let node = chart;
  for (let i = 0; i < 6 && node; i++) {
    const root = node.getRootNode?.();
    node = root?.host;
    if (!node) return null;
    const style =
      node._config?.[LINE_KEY] ??
      node.config?.[LINE_KEY] ??
      node.parentElement?.config?.[LINE_KEY];
    if (style) return style;
  }
  return null;
}

function styleSeries(data, style) {
  if (!Array.isArray(data)) return data;
  return data.map((s) =>
    s && s.type === "line"
      ? {
          ...s,
          smooth: style === "smooth" ? 0.4 : false,
          step: style === "stepped" ? "end" : false,
        }
      : s
  );
}

function patchChartBase(cls) {
  const proto = cls?.prototype;
  if (!proto || proto[MARK]) return;
  const original = proto.willUpdate;
  proto.willUpdate = function (changed) {
    try {
      if (changed?.has?.("data")) {
        const style = lineStyleFor(this);
        if (style && style !== "smooth") {
          this.data = styleSeries(this.data, style);
        }
      }
    } catch (e) {
      console.warn(TAG, "could not apply line style", e);
    }
    return original?.call(this, changed);
  };
  proto[MARK] = true;
}

installRegistryHooks();
// Keep checking for a replaced registry for a while after start-up.
const hookTimer = setInterval(installRegistryHooks, 100);
setTimeout(() => clearInterval(hookTimer), 120000);
